INSERT INTO feature VALUES('bridge-types','identity','Bridge types by the identity recursion',NULL,'partial','unique','dependent provers','The bridge relation by the identity recursion in bridge mode, interval-free: Unit, Base, sums, products, a function code as the family over argument bridges, the value universe at any level as a relation, the List lifting; persisted as the Bridge node (tag 0x36) and replayed; a sealed atom supplies its element relation and reflexivity as fields of its declaration, read at its bridges, and an atom without them is refused by name; transport, coherence and J not granted. The surface writes `Bridge(a, b)` with term endpoints, or supplies the carrier by name, `Bridge[.A = A](a, b)`, and the core checks an introduction at the fibre its bridge fold reads, a sealed type and a code outside the fold refused by name; the model laws owed.','kernel-core kernel-term core-checker surface-grammar surface-lowering surface-pretty','crates/kernel-core/tests/bridge_readmission.rs crates/kernel-core/src/identity_recursion.rs crates/kernel-core/src/element_identity/bridge_tests.rs crates/kernel-core/src/element_identity/bridge_tests.rs::the_lawful_atom crates/core-checker-bridge/src/bridge/tests/bridges.rs crates/surface-lowering/src/lower/identity/tests.rs::a_bridge_type_lowers_to_the_core_bridge_3427 corpus/model/identity/bridge.gandr corpus/pathological/identity/bridge.gandr corpus/model/identity/carrier-by-name.gandr','corpus/ledger/features/bridge-types.gandr','#3519');
